请对以下 case 进行三维加权评分。

=== case_id ===
Case-28-veggie-price-002

=== 用户原始指令 (query.txt) ===
整个卡片要带数字的一行,点跳应用,能读天气,要有快不行提醒

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个卡片要带数字的一行,点跳应用,能读天气,要有快不行提醒",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询地区名称，用于标识当前菜价比价参考区域。",
            "sampleValue": "本地"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本，可作为菜价关注的天气数字提示。",
            "sampleValue": "32°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "雷雨"
          },
          "humidityPercent": {
            "type": "number",
            "description": "当前相对湿度百分比。",
            "sampleValue": 78
          },
          "windLevel": {
            "type": "integer",
            "description": "当前风力等级。",
            "sampleValue": 3
          },
          "alertLevel": {
            "type": "string",
            "description": "当前天气预警信息，用于快不行提醒。",
            "sampleValue": "高温橙色预警"
          }
        },
        "daily": [
          {
            "temperatureRangeText": {
              "type": "string",
              "description": "今日温度范围展示文本。",
              "sampleValue": "28° / 35°"
            },
            "rainProbabilityPercent": {
              "type": "string",
              "description": "今日降雨概率百分比。",
              "sampleValue": "73%"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/thunderstorm.png",
      "description": "云朵、闪电和雨滴组合的彩色天气图标，适合雷雨、高温或菜价波动提醒场景。"
    }
  ]
}

